const WA='https://wa.me/8801982561926';
const SHEET_API_URL="https://script.google.com/macros/s/AKfycbxdNs8g1OxiyKuHyFp-CQkY6n09j2veUAznAafFw52TDKLlATSG6w1mDgjQQ6kpk1t17g/exec";
const bn=n=>Number(n).toLocaleString('bn-BD');
const PAGE_SIZE=8;
let visibleCount=PAGE_SIZE;
let activeFilter='all';
function isAvailable(p){return !['NOT AVAILABLE','NOT_AVAILABLE','UNAVAILABLE','FALSE','SOLD OUT','OUT OF STOCK'].includes(String(p.availability??'Available').trim().toUpperCase());}
function isVisibleProduct(p){return p.status!==false&&String(p.status).toUpperCase()!=='FALSE';}
function fixedPrice(p){
  if(p.price===''||p.price==null||!Number.isFinite(Number(p.price))||Number(p.price)<=0)return '';
  return `${bn(p.price)} ৳ — ১ পাউন্ডের দাম`;
}
function productOrder(){
  return PRODUCTS.filter(isVisibleProduct).slice().sort((a,b)=>Number(isAvailable(b))-Number(isAvailable(a)));
}
function renderProducts(){
  const grid=document.getElementById('cakeGrid');
  grid.innerHTML=productOrder().map(p=>{
    const available=isAvailable(p),price=fixedPrice(p);
    return `<article class="cake-card ${available?'':'is-unavailable'}" data-category="${p.category}" data-name="${p.name}" data-available="${available?'yes':'no'}">
      <div class="cake-image-wrap"><img class="cake-img" src="${p.image}" alt="${p.name}" loading="lazy" data-open="${p.id}">${available?'':'<span class="availability-ribbon">Not Available</span>'}</div>
      <div class="cake-meta"><h3>${p.name}</h3><p>${p.description}</p><div class="cake-bottom">${available?`<span class="price">${price||'দাম জানতে যোগাযোগ করুন'}</span>`:'<span class="unavailable-text">Not Available</span>'}${available?`<button class="order-mini" data-open="${p.id}">বিস্তারিত</button>`:'<button class="order-mini unavailable-btn" type="button" disabled>Not Available</button>'}</div></div>
    </article>`;
  }).join('');
  visibleCount=PAGE_SIZE;
  applyFilters();
}
function applyFilters(){
  const q=document.getElementById('cakeSearch').value.trim().toLocaleLowerCase('bn');
  const cards=Array.from(document.querySelectorAll('.cake-card'));
  const matches=cards.filter(c=>(activeFilter==='all'||c.dataset.category===activeFilter)&&(!q||c.dataset.name.toLocaleLowerCase('bn').includes(q)));
  cards.forEach(c=>c.classList.add('hide'));
  matches.slice(0,visibleCount).forEach(c=>c.classList.remove('hide'));
  document.getElementById('emptyState').style.display=matches.length?'none':'block';
  const wrap=document.getElementById('loadMoreWrap');
  wrap.style.display=matches.length>visibleCount?'block':'none';
  document.getElementById('loadMoreBtn').textContent=`আরও কেক দেখুন (${bn(matches.length-visibleCount)}টি) ↓`;
}
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{
  document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));
  b.classList.add('active');activeFilter=b.dataset.filter;visibleCount=PAGE_SIZE;applyFilters();
}));
document.getElementById('cakeSearch').addEventListener('input',()=>{visibleCount=PAGE_SIZE;applyFilters();});
document.getElementById('loadMoreBtn').addEventListener('click',()=>{visibleCount+=PAGE_SIZE;applyFilters();});
function cakeShareUrl(p){return `${location.origin}${location.pathname}#cake=${encodeURIComponent(p.id)}`;}
function openCake(id,fromDeepLink=false){
 const p=PRODUCTS.find(x=>x.id===id);if(!p)return;
 const available=isAvailable(p),price=fixedPrice(p);
 document.getElementById('modalCakeImg').src=p.image;
 document.getElementById('modalCakeImg').alt=p.name;
 document.getElementById('modalCakeName').textContent=p.name;
 document.getElementById('modalCakeDesc').textContent=p.description;
 const priceEl=document.getElementById('modalCakePrice');
 priceEl.textContent=available?(price||'দাম জানতে যোগাযোগ করুন'):'';
 priceEl.style.display=available?'':'none';
 const order=document.getElementById('modalOrder');
 if(available){
   const url=cakeShareUrl(p);
   const msg=`আসসালামু আলাইকুম।\nআমি আপনাদের “${p.name}” ডিজাইনটি পছন্দ করেছি। এই কেকটির ১ পাউন্ডের দাম, সাইজ/ওজন ও ফ্লেভারের বিস্তারিত জানাবেন?\n\nনির্দিষ্ট কেকের লিংক: ${url}\n\nধন্যবাদ। ❤️`;
   order.href=WA+'?text='+encodeURIComponent(msg);order.style.display='';
 }else{order.removeAttribute('href');order.style.display='none';}
 document.getElementById('cakeModal').classList.add('show');
 if(!fromDeepLink)history.replaceState(null,'',location.pathname+location.search+'#cake='+encodeURIComponent(p.id));
}
function closeModal(id){const el=document.getElementById(id);if(el)el.classList.remove('show');if(id==='cakeModal'&&location.hash.startsWith('#cake='))history.replaceState(null,'',location.pathname+location.search);}
function reviewImages(){return Array.from(document.querySelectorAll('.review-img'));}let currentReviewIndex=0,reviewTouchStartX=0;
function showReview(index){const imgs=reviewImages();if(!imgs.length)return;currentReviewIndex=(index+imgs.length)%imgs.length;const source=imgs[currentReviewIndex],big=document.getElementById('lightboxImg');big.src=source.src;big.alt=source.alt||`কাস্টমার রিভিউ ${currentReviewIndex+1}`;document.getElementById('reviewCounter').textContent=`${bn(currentReviewIndex+1)} / ${bn(imgs.length)}`;document.getElementById('lightbox').classList.add('show');}
document.addEventListener('click',e=>{const opener=e.target.closest('[data-open]');if(opener){openCake(opener.dataset.open);return;}const closer=e.target.closest('[data-close]');if(closer){closeModal(closer.dataset.close);return;}const nav=e.target.closest('[data-review-nav]');if(nav){showReview(currentReviewIndex+(nav.dataset.reviewNav==='next'?1:-1));return;}const review=e.target.closest('.review-shot');if(review){showReview(reviewImages().indexOf(review.querySelector('.review-img')));}});
document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m.id);}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modal.show').forEach(m=>closeModal(m.id));if(document.getElementById('lightbox').classList.contains('show')){if(e.key==='ArrowRight')showReview(currentReviewIndex+1);if(e.key==='ArrowLeft')showReview(currentReviewIndex-1);}});
const lightbox=document.getElementById('lightbox');lightbox.addEventListener('touchstart',e=>{reviewTouchStartX=e.changedTouches[0].screenX;},{passive:true});lightbox.addEventListener('touchend',e=>{const dx=e.changedTouches[0].screenX-reviewTouchStartX;if(Math.abs(dx)>45)showReview(currentReviewIndex+(dx<0?1:-1));},{passive:true});
function applySheetPrices(rows){
 if(!Array.isArray(rows))return;
 const byId=new Map(rows.map(x=>[String(x.id).trim(),x]));
 PRODUCTS.forEach(p=>{
   const r=byId.get(String(p.id).trim());
   if(r){
     if(r.price!==undefined&&r.price!==null)p.price=r.price;
     if(r.status!==undefined&&r.status!==null&&String(r.status).trim()!=='')p.status=r.status;
     p.availability=(r.availability!==undefined&&String(r.availability).trim()!=='')?r.availability:(p.availability||'Available');
   }
 });
 renderProducts();
}
window.receiveCakePrices=applySheetPrices;
function loadSheetPrices(){
 if(!SHEET_API_URL)return;
 const s=document.createElement('script');
 s.src=SHEET_API_URL+(SHEET_API_URL.includes('?')?'&':'?')+'callback=receiveCakePrices&_='+Date.now();
 s.async=true;s.onerror=()=>console.warn('Google Sheet update unavailable; local product data is shown.');
 document.head.appendChild(s);
}
renderProducts();loadSheetPrices();if(location.hash.startsWith('#cake=')){const id=decodeURIComponent(location.hash.slice(6));openCake(id,true);}

/* Premium mobile navigation: independent of product, Sheets and WhatsApp flows */
(function(){
  const toggle=document.querySelector('.menu-toggle');
  const menu=document.querySelector('.menu');
  if(!toggle||!menu)return;
  const closeMenu=()=>{menu.classList.remove('is-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','মেনু খুলুন');toggle.textContent='☰';};
  toggle.addEventListener('click',()=>{
    const open=menu.classList.toggle('is-open');
    toggle.setAttribute('aria-expanded',String(open));
    toggle.setAttribute('aria-label',open?'মেনু বন্ধ করুন':'মেনু খুলুন');
    toggle.textContent=open?'×':'☰';
  });
  menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
  document.addEventListener('click',e=>{if(!menu.contains(e.target)&&!toggle.contains(e.target))closeMenu();});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
  window.addEventListener('resize',()=>{if(window.innerWidth>650)closeMenu();});
})();
